    necessary = [True] * N
    for i in range(N):
        if sum(a[:i] + a[i+1:]) >= K:
            continue
        for j in range(1 << (N-1)):
            subset_sum = 0
            for k in range(N-1):
                if j & (1 << k):
                    subset_sum += a[k]
            if subset_sum >= K and (j | (1 << i)) == ((1 << (N-1)) - 1):
                necessary[i] = False
