def count_unnecessary_cards(N, K, cards):
    if sum(cards) < K:
        return N

    necessary = [False] * N
    total_sum = sum(cards)

    def is_good_subset(subset_sum, remaining_sum):
        return subset_sum >= K or remaining_sum >= K

    for i in range(1 << N):
        subset_sum = 0
        remaining_sum = total_sum
        for j in range(N):
            if i & (1 << j):
                subset_sum += cards[j]
                remaining_sum -= cards[j]

        if is_good_subset(subset_sum, remaining_sum):
            for j in range(N):
                if i & (1 << j):
                    necessary[j] = True

    return N - sum(necessary)

